import React, { useState, useEffect } from 'react';

interface HeaderProps {
  onJoinClick?: () => void;
}

const Header: React.FC<HeaderProps> = ({ onJoinClick }) => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-glass py-3 shadow-md' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <div className="flex items-center space-x-2">
          <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold text-xl">D</div>
          <span className={`text-xl font-bold tracking-tight ${isScrolled ? 'text-blue-900' : 'text-white'}`}>Dream it marketing</span>
        </div>

        <div className="hidden md:flex space-x-8">
          {['Home', 'About', 'Resorts', 'Membership'].map((item) => (
            <a 
              key={item} 
              href={`#${item.toLowerCase()}`}
              className={`font-medium transition-colors hover:text-blue-500 ${isScrolled ? 'text-slate-700' : 'text-white'}`}
            >
              {item}
            </a>
          ))}
        </div>

        <button 
          onClick={onJoinClick}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-full font-semibold transition-all transform hover:scale-105"
        >
          Join the Club
        </button>
      </div>
    </nav>
  );
};

export default Header;

import React, { useState, useEffect, useRef } from 'react';

interface ContactFormModalProps {
  onClose: () => void;
}

const ContactFormModal: React.FC<ContactFormModalProps> = ({ onClose }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    interest: '',
    dream: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const totalSteps = 4;

  const nextStep = () => {
    if (step < totalSteps) setStep(step + 1);
    else handleSubmit();
  };

  const prevStep = () => {
    if (step > 1) setStep(step - 1);
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1500));
    setStep(5); // Success step
    setIsSubmitting(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && step < 5) {
      if (step === 1 && !formData.name) return;
      if (step === 2 && (!formData.email || !formData.phone)) return;
      nextStep();
    }
  };

  const progress = (step / totalSteps) * 100;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4" onKeyDown={handleKeyDown}>
      <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-2xl" onClick={onClose}></div>

      {/* Progress Bar */}
      {step <= totalSteps && (
        <div className="fixed top-0 left-0 w-full h-1.5 bg-white/10 z-[110]">
          <div 
            className="h-full bg-blue-500 transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          ></div>
        </div>
      )}

      <div className="relative w-full max-w-2xl text-white">
        <button 
          onClick={onClose}
          className="absolute -top-16 right-0 md:-right-16 w-12 h-12 rounded-full hover:bg-white/10 flex items-center justify-center transition-colors text-white/50 hover:text-white"
        >
          <i className="fas fa-times text-2xl"></i>
        </button>

        <div className="space-y-12">
          {step === 1 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-6">
                <span className="text-blue-400 font-bold text-lg">01 →</span>
                <h2 className="text-3xl md:text-5xl font-bold serif">What should we call you? *</h2>
              </div>
              <input 
                autoFocus
                type="text"
                placeholder="Type your full name here..."
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full bg-transparent border-b-2 border-white/20 py-4 text-2xl md:text-4xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20"
              />
              <div className="mt-8 flex items-center gap-4">
                <button 
                  onClick={nextStep}
                  disabled={!formData.name}
                  className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 px-8 py-3 rounded-lg font-bold transition-all flex items-center gap-2"
                >
                  OK <i className="fas fa-check"></i>
                </button>
                <span className="text-xs text-white/40">press <span className="font-bold">ENTER</span></span>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-6">
                <span className="text-blue-400 font-bold text-lg">02 →</span>
                <h2 className="text-3xl md:text-5xl font-bold serif">Where can we reach you?</h2>
              </div>
              <div className="space-y-8">
                <input 
                  autoFocus
                  type="email"
                  placeholder="Email address..."
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full bg-transparent border-b-2 border-white/20 py-4 text-2xl md:text-4xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20"
                />
                <input 
                  type="tel"
                  placeholder="Phone number..."
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  className="w-full bg-transparent border-b-2 border-white/20 py-4 text-2xl md:text-4xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20"
                />
              </div>
              <div className="mt-12 flex items-center gap-6">
                <button 
                  onClick={nextStep}
                  disabled={!formData.email || !formData.phone}
                  className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 px-8 py-3 rounded-lg font-bold transition-all flex items-center gap-2"
                >
                  Continue
                </button>
                <button onClick={prevStep} className="text-white/40 hover:text-white text-sm flex items-center gap-2">
                  <i className="fas fa-chevron-up"></i> Go back
                </button>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-8">
                <span className="text-blue-400 font-bold text-lg">03 →</span>
