 *      var data = JSON.parse(e.postData.contents);
 *      sheet.appendRow([new Date(), data.name, data.email, data.phone, data.interest, data.dream]);
 *      return ContentService.createTextOutput(JSON.stringify({result: 'success'})).setMimeType(ContentService.MimeType.JSON);
 *    }
 * 
 * 4. Click 'Deploy' > 'New Deployment'. Select 'Web App'.
 * 5. Set 'Execute as' to 'Me' and 'Who has access' to 'Anyone'.
 * 6. Copy the Web App URL and paste it into the 'scriptURL' variable below.
 */

const scriptURL = ''; // Paste your Google Apps Script Web App URL here to enable the live spreadsheet connection

const ContactFormModal: React.FC<ContactFormModalProps> = ({ onClose }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    interest: '',
    dream: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const totalSteps = 4;

  const nextStep = () => {
    if (step < totalSteps) setStep(step + 1);
    else handleSubmit();
  };

  const prevStep = () => {
    if (step > 1) setStep(step - 1);
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    setError(null);

    try {
      if (scriptURL) {
        // Send data to Google Sheet via the Apps Script Web App
        await fetch(scriptURL, {
          method: 'POST',
          mode: 'no-cors', 
          cache: 'no-cache',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            ...formData,
            timestamp: new Date().toISOString()
          }),
        });
        setStep(5);
      } else {
        // Fallback demo mode if scriptURL is missing
        console.warn("Spreadsheet link active but Web App URL missing. Captured Data:", formData);
        await new Promise(resolve => setTimeout(resolve, 1500));
        setStep(5);
      }
    } catch (err) {
      console.error("Submission error:", err);
      setError("We encountered a connection issue. Please check your signal and try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && step < 5) {
      if (step === 1 && !formData.name) return;
      if (step === 2 && (!formData.email || !formData.phone)) return;
      nextStep();
    }
  };

  const progress = (step / totalSteps) * 100;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4" onKeyDown={handleKeyDown}>
      <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-2xl" onClick={onClose}></div>

      {/* Progress Bar */}
      {step <= totalSteps && (
        <div className="fixed top-0 left-0 w-full h-1.5 bg-white/10 z-[110]">
          <div 
            className="h-full bg-blue-500 transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          ></div>
        </div>
      )}

      <div className="relative w-full max-w-2xl text-white">
        <button 
          onClick={onClose}
          className="absolute -top-16 right-0 md:-right-16 w-12 h-12 rounded-full hover:bg-white/10 flex items-center justify-center transition-colors text-white/50 hover:text-white"
        >
          <i className="fas fa-times text-2xl"></i>
        </button>

        <div className="space-y-12">
          {step === 1 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-6">
                <span className="text-blue-400 font-bold text-lg">01 →</span>
                <h2 className="text-3xl md:text-5xl font-bold serif">What should we call you? *</h2>
              </div>
              <input 
                autoFocus
                type="text"
                placeholder="Type your full name here..."
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full bg-transparent border-b-2 border-white/20 py-4 text-2xl md:text-4xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20"
              />
              <div className="mt-8 flex items-center gap-4">
                <button 
                  onClick={nextStep}
                  disabled={!formData.name}
                  className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 px-8 py-3 rounded-lg font-bold transition-all flex items-center gap-2"
                >
                  OK <i className="fas fa-check"></i>
                </button>
                <span className="text-xs text-white/40">press <span className="font-bold">ENTER</span></span>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-6">
                <span className="text-blue-400 font-bold text-lg">02 →</span>
                <h2 className="text-3xl md:text-5xl font-bold serif">Where can we reach you?</h2>
              </div>
              <div className="space-y-8">
                <input 
                  autoFocus
                  type="email"
                  placeholder="Email address..."
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full bg-transparent border-b-2 border-white/20 py-4 text-2xl md:text-4xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20"
                />
                <input 
                  type="tel"
                  placeholder="Phone number..."
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  className="w-full bg-transparent border-b-2 border-white/20 py-4 text-2xl md:text-4xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20"
                />
              </div>
              <div className="mt-12 flex items-center gap-6">
                <button 
                  onClick={nextStep}
                  disabled={!formData.email || !formData.phone}
                  className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 px-8 py-3 rounded-lg font-bold transition-all flex items-center gap-2"
                >
                  Continue
                </button>
                <button onClick={prevStep} className="text-white/40 hover:text-white text-sm flex items-center gap-2">
                  <i className="fas fa-chevron-up"></i> Go back
                </button>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-8">
                <span className="text-blue-400 font-bold text-lg">03 →</span>
                <h2 className="text-3xl md:text-5xl font-bold serif">Which horizon calls to you?</h2>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {['Safari Collection', 'Coastal Escapes', 'Alpine Lodges', 'International Portfolios'].map((opt) => (
                  <button
                    key={opt}
                    onClick={() => { setFormData({ ...formData, interest: opt }); nextStep(); }}
                    className={`text-left p-6 rounded-xl border-2 transition-all group ${formData.interest === opt ? 'bg-blue-600 border-blue-600 shadow-xl scale-[1.02]' : 'bg-white/5 border-white/10 hover:border-white/30'}`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="text-xl font-semibold">{opt}</span>
                      <span className={`w-8 h-8 rounded border flex items-center justify-center text-xs font-bold transition-colors ${formData.interest === opt ? 'bg-white text-blue-600 border-white' : 'border-white/20 group-hover:border-white/50'}`}>
                        {opt[0]}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
              <div className="mt-8">
                <button onClick={prevStep} className="text-white/40 hover:text-white text-sm flex items-center gap-2">
                  <i className="fas fa-chevron-up"></i> Go back
                </button>
              </div>
            </div>
          )}

          {step === 4 && (
            <div className="animate-[slideIn_0.5s_ease-out]">
              <div className="flex items-center gap-4 mb-6">
                <span className="text-blue-400 font-bold text-lg">04 →</span>
                <h2 className="text-3xl md:text-5xl font-bold serif">Tell us about your dream holiday.</h2>
              </div>
              <textarea 
                autoFocus
                placeholder="I dream of waking up to..."
                value={formData.dream}
                onChange={(e) => setFormData({ ...formData, dream: e.target.value })}
                className="w-full bg-transparent border-b-2 border-white/20 py-4 text-xl md:text-2xl focus:outline-none focus:border-blue-500 transition-colors placeholder:text-white/20 min-h-[150px] resize-none"
              />
              {error && (
                <p className="mt-4 text-red-400 text-sm flex items-center gap-2">
                  <i className="fas fa-exclamation-circle"></i> {error}
                </p>
              )}
              <div className="mt-12 flex items-center gap-6">
                <button 
                  onClick={handleSubmit}
                  disabled={isSubmitting}
                  className="bg-blue-600 hover:bg-blue-700 px-10 py-4 rounded-xl font-bold text-lg transition-all flex items-center gap-3 shadow-2xl shadow-blue-500/20"
                >
                  {isSubmitting ? (
                    <>
                      <i className="fas fa-spinner animate-spin"></i>
                      <span>Recording...</span>
                    </>
                  ) : 'Submit Inquiry'}
                </button>
                <button onClick={prevStep} className="text-white/40 hover:text-white text-sm flex items-center gap-2">
                  <i className="fas fa-chevron-up"></i> Go back
                </button>
              </div>
            </div>
          )}

          {step === 5 && (
            <div className="text-center animate-[scaleIn_0.5s_ease-out] py-12">
              <div className="w-24 h-24 bg-blue-600 text-white rounded-full flex items-center justify-center text-4xl mx-auto mb-8 shadow-2xl shadow-blue-500/40">
                <i className="fas fa-paper-plane"></i>
              </div>
              <h2 className="text-4xl md:text-6xl font-bold mb-6 serif">A world of luxury awaits.</h2>
              <p className="text-xl text-white/60 max-w-lg mx-auto leading-relaxed mb-12">
                Thank you, {formData.name.split(' ')[0]}. Your interest has been logged. Our concierge will be in touch shortly to refine your escape.
              </p>
              <button 
                onClick={onClose}
                className="border-2 border-white/20 hover:border-white text-white px-10 py-3 rounded-full font-bold transition-all"
              >
                Return to Site
              </button>
            </div>
          )}
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes slideIn {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
      `}} />
    </div>
  );
};

export default ContactFormModal;

