          },
          required: ["marketCost", "memberCost", "savingsAmount", "savingsPercentage", "inclusions", "conciergeInsight"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Budget AI Error:", error);
    throw error;
  }
};

