/**
 * Service to calculate travel budgets and membership savings.
 * Grounded in South African luxury market rates.
 */
export const getBudgetEstimate = async (params: {
  destination: string;
  adults: number;
  children: number;
  nights: number;
  tier: 'Standard' | 'Premium' | 'Ultra-Luxe';
}) => {
  try {
    const prompt = `
      Calculate a realistic luxury vacation budget for a ${params.nights}-night stay in a "${params.destination}" destination.
      Party: ${params.adults} adults, ${params.children} children.
      Luxury Tier: ${params.tier}

      MARKET ANCHORS (ZAR per night):
      - Standard: ~R3,000 - R4,500
      - Premium: ~R6,000 - R9,500
      - Ultra-Luxe: ~R18,000 - R35,000

      DREAM VACATION CLUB ADVANTAGE:
      Members typically save 45-60% because they utilize a points-based/pre-paid system.

      Generate a JSON response with:
      1. marketCost: Total public price for the stay.
      2. memberCost: Total price for members (Maintenance/Points value).
      3. perNightMarket: Average public nightly rate.
      4. perNightMember: Average member nightly rate.
      5. tenYearSavings: Estimated savings if this trip was taken annually for 10 years.
      6. inclusions: 3 high-end perks (e.g., Private Game Drive, Spa Credit).
      7. insight: A sophisticated tip about the financial wisdom of this destination.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            marketCost: { type: Type.NUMBER },
            memberCost: { type: Type.NUMBER },
            perNightMarket: { type: Type.NUMBER },
            perNightMember: { type: Type.NUMBER },
            tenYearSavings: { type: Type.NUMBER },
            savingsPercentage: { type: Type.INTEGER },
            inclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
            insight: { type: Type.STRING }
          },
          required: ["marketCost", "memberCost", "perNightMarket", "perNightMember", "tenYearSavings", "inclusions", "insight"]
        }
      }
    });

    const data = JSON.parse(response.text || '{}');
    // Ensure savingsPercentage is calculated if AI missed it
    data.savingsPercentage = Math.round(((data.marketCost - data.memberCost) / data.marketCost) * 100);
    return data;
  } catch (error) {
    console.error("Budget AI Error:", error);
    throw error;
  }
};

