const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getHolidayRecommendation = async (
  preferences: string,
  destinationType: string,
  startDate: string,
  endDate: string,
  guests: string
): Promise<string> => {
  try {
    const prompt = `
      Act as an elite travel concierge for "Dream it marketing". 
      Based on these trip details:
      - Preferred Environment: ${destinationType}
      - Travel Window: ${startDate} to ${endDate}
      - Party Size: ${guests} guest(s)
      - Personal Desires: "${preferences}"

      Provide a 3-sentence luxury vacation recommendation that highlights the importance of "time" and "effortless experiences". 
      Focus on high-end quality and the brand's exclusive South African portfolio. 
      The tone should be sophisticated, inviting, and reassuring.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "We've imagined a beautiful stay for you. Let's make it a reality.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error generating your dream. Please try again.";
  }
};

/**
 * Service to calculate travel budgets and membership savings.
 * Grounded in South African luxury market rates and specific Portfolio benchmarks.
 */
export const getBudgetEstimate = async (params: {
  destination: string;
  adults: number;
  children: number;
  nights: number;
  tier: 'Standard' | 'Premium' | 'Ultra-Luxe';
}) => {
  try {
    const prompt = `
      Calculate a realistic luxury vacation budget for a ${params.nights}-night stay at "${params.destination}".
      Party: ${params.adults} adults, ${params.children} children.
      Luxury Tier: ${params.tier}

      CONTEXT FOR DREAM VACATION CLUB PORTFOLIO:
      If the destination is one of these, use specific South African market data:
      - Mount Amanzi: Family riverfront, Magaliesberg. Public ~R2,800 - R4,000/night.
      - Finfoot Lake Reserve: Luxury Safari/Lake. Public ~R5,500 - R8,500/night.
      - Alpine Heath Resort: Berg retreat. Public ~R4,500 - R7,000/night.
      - Breakers Resort: Umhlanga beachfront. Public ~R5,000 - R9,000/night.
      - Blue Marlin Hotel: South Coast iconic. Public ~R3,000 - R5,500/night.
      - The Peninsula: Sea Point All-Suite. Public ~R6,000 - R12,000/night.

      DREAM CLUB ADVANTAGE:
      Members do not pay these public nightly rates. They use a points/pre-paid system. 
      Their "cost" is effectively a maintenance levy or points value, usually 50-70% LOWER than public rates for these specific properties.

      Generate a JSON response with:
      1. isPortfolioResort: boolean (true if it's one of the 6 named above)
      2. marketCost: Total public price for the stay.
      3. memberCost: Total price for members (Maintenance/Points value).
      4. perNightMarket: Average public nightly rate.
      5. perNightMember: Average member nightly rate.
      6. tenYearSavings: Estimated savings if this trip was taken annually for 10 years.
      7. inclusions: 3 high-end perks (e.g., Private Game Drive, Spa Credit).
      8. insight: A sophisticated tip about the financial wisdom of this specific resort.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isPortfolioResort: { type: Type.BOOLEAN },
            marketCost: { type: Type.NUMBER },
            memberCost: { type: Type.NUMBER },
            perNightMarket: { type: Type.NUMBER },
            perNightMember: { type: Type.NUMBER },
            tenYearSavings: { type: Type.NUMBER },
            savingsPercentage: { type: Type.INTEGER },
            inclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
            insight: { type: Type.STRING }
          },
          required: ["isPortfolioResort", "marketCost", "memberCost", "perNightMarket", "perNightMember", "tenYearSavings", "inclusions", "insight"]
        }
      }
    });

    const data = JSON.parse(response.text || '{}');
    data.savingsPercentage = Math.round(((data.marketCost - data.memberCost) / data.marketCost) * 100);
    return data;
  } catch (error) {
    console.error("Budget AI Error:", error);
    throw error;
  }
};

