export const getHolidayRecommendation = async (
  preferences: string,
  destinationType: string,
  startDate: string,
  endDate: string,
  guests: string
): Promise<string> => {
  try {
    const prompt = `
      Act as an elite travel concierge for "Dream it marketing". 
      Based on these trip details:
      - Preferred Environment: ${destinationType}
      - Travel Window: ${startDate} to ${endDate}
      - Party Size: ${guests} guest(s)
      - Personal Desires: "${preferences}"

      Provide a 3-sentence luxury vacation recommendation that highlights the importance of "time" and "effortless experiences". 
      Focus on high-end quality and the brand's exclusive South African portfolio. 
      The tone should be sophisticated, inviting, and reassuring.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "We've imagined a beautiful stay for you. Let's make it a reality.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error generating your dream. Please try again.";
  }
};

/**
 * Service to calculate travel budgets and membership savings.
 * Grounded in South African luxury market rates and specific Portfolio benchmarks.
 * Now includes Seasonal Intelligence.
 */
export const getBudgetEstimate = async (params: {
  destination: string;
  adults: number;
  children: number;
  nights: number;
  tier: 'Standard' | 'Premium' | 'Ultra-Luxe';
  travelDate: string;
}) => {
  try {
    const prompt = `
      Calculate a realistic luxury vacation budget for a ${params.nights}-night stay at "${params.destination}" starting on ${params.travelDate}.
      Party: ${params.adults} adults, ${params.children} children.
      Luxury Tier: ${params.tier}

      SEASONAL INTELLIGENCE (South African Context):
      - Peak (Dec 15 - Jan 10, Easter): Market prices surge by 50-100%. 
      - Mid-Peak (Sept, Oct, April): High demand, standard luxury rates.
      - Off-Peak (May - Aug): Market prices often discounted, except for Safari which remains stable.

      DREAM CLUB ADVANTAGE:
      Member costs (levies/points) are generally FIXED regardless of season. This is the primary value prop.
      Compare the massive seasonal surge of public sites vs the stable member value.

      CONTEXT FOR PORTFOLIO:
      - Mount Amanzi, Finfoot, Alpine Heath, Breakers, Blue Marlin, Peninsula.

      Generate a JSON response with:
      1. isPortfolioResort: boolean
      2. seasonType: string (e.g., "Peak Summer", "Mid-Season", "Winter Escape")
      3. marketCost: Total public price for the stay (inflation-adjusted for the season).
      4. memberCost: Total price for members (Maintenance/Points value - stays stable).
      5. perNightMarket: Average public nightly rate.
      6. perNightMember: Average member nightly rate.
      7. tenYearSavings: Estimated savings if this trip was taken annually for 10 years.
      8. inclusions: 3 high-end perks.
      9. insight: A sophisticated tip about the financial wisdom of this specific date and resort.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isPortfolioResort: { type: Type.BOOLEAN },
            seasonType: { type: Type.STRING },
            marketCost: { type: Type.NUMBER },
            memberCost: { type: Type.NUMBER },
            perNightMarket: { type: Type.NUMBER },
            perNightMember: { type: Type.NUMBER },
            tenYearSavings: { type: Type.NUMBER },
            savingsPercentage: { type: Type.INTEGER },
            inclusions: { type: Type.ARRAY, items: { type: Type.STRING } },
            insight: { type: Type.STRING }
          },
          required: ["isPortfolioResort", "seasonType", "marketCost", "memberCost", "perNightMarket", "perNightMember", "tenYearSavings", "inclusions", "insight"]
        }
      }
    });

    const data = JSON.parse(response.text || '{}');
    data.savingsPercentage = Math.round(((data.marketCost - data.memberCost) / data.marketCost) * 100);
    return data;
  } catch (error) {
    console.error("Budget AI Error:", error);
    throw error;
  }
};

