              <h3 className="text-2xl font-bold text-white mb-2 serif tracking-tight">Access the Extended Portfolio</h3>
              <p className="text-slate-400 text-sm max-w-md">
                Browse our complete South African collection. From hidden gems in the Magaliesberg to exclusive Kruger Park lodges.
              </p>
            </div>

            <div className="w-full md:w-auto min-w-[320px]">
              <div className="relative">
                <select 
                  onChange={handleExtendedSelection}
                  defaultValue=""
                  className="w-full bg-white/5 border border-white/10 text-white rounded-xl px-6 py-4 appearance-none focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all cursor-pointer font-medium"
