import React, { useState, useEffect } from 'react';
import { getBudgetEstimate } from '../services/geminiService';

const PORTFOLIO_RESORTS = [
  'Mount Amanzi',
  'Finfoot Lake Reserve',
  'Alpine Heath Resort',
  'Breakers Resort',
  'Blue Marlin Hotel',
  'The Peninsula'
